// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 ts) public {
        vm.assume(actor != address(0) && actor != address(c));
        // admissible: the call time must be in the future relative to the current block number
        vm.assume(ts > block.number && ts < type(uint256).max - 1);
        vm.roll(block.number); // keep current block number fixed
        vm.warp(ts);
        vm.deal(actor, 20 ether);

        // first call at time ts succeeds
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // GENERAL RULE: the same timestamp cannot be used twice;
        // an immediate second call at time ts must revert.
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second call at the same timestamp must revert");
    }
}
